// Сборка инструкции для клиента в .docx (конструктор футболок).
// Пересобрать: npm install --no-save docx && node docs/build/make-tshirt-instruction-docx.cjs
const fs = require('fs');
const path = require('path');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, LevelFormat
} = require('docx');

const ACCENT = '14294C';
const MUTED = '6B6459';
const LINE = 'DAD0BD';
const WARN = 'FDF2E0';
const TABLE_W = 9360;

const t = (text, opts = {}) => new TextRun({ text, ...opts });
const arr = (x) => (Array.isArray(x) ? x : [t(x)]);
const p = (children, opts = {}) => new Paragraph({ children: arr(children), spacing: { after: 140, line: 276 }, ...opts });
const h1 = (text) => new Paragraph({ text, heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 160 } });
const h2 = (text) => new Paragraph({ text, heading: HeadingLevel.HEADING_2, spacing: { before: 260, after: 120 } });
const code = (text) => t(text, { font: 'Consolas', size: 20, color: ACCENT });

const callout = (children) => new Paragraph({
  children: arr(children),
  spacing: { before: 120, after: 160, line: 276 },
  indent: { left: 220, right: 220 },
  shading: { type: ShadingType.CLEAR, fill: WARN },
  border: {
    top: { style: BorderStyle.SINGLE, size: 2, color: LINE },
    bottom: { style: BorderStyle.SINGLE, size: 2, color: LINE },
    left: { style: BorderStyle.SINGLE, size: 12, color: 'E0922F' },
    right: { style: BorderStyle.SINGLE, size: 2, color: LINE }
  }
});

const cell = (content, opts) => new TableCell({
  width: { size: opts.width, type: WidthType.DXA },
  margins: { top: 90, bottom: 90, left: 140, right: 140 },
  shading: opts.header ? { type: ShadingType.CLEAR, fill: 'F4EFE3' } : undefined,
  children: [new Paragraph({
    children: [t(content, { bold: !!opts.header, color: opts.header ? ACCENT : undefined })],
    spacing: { after: 0 }
  })]
});

const bd = { style: BorderStyle.SINGLE, size: 2, color: LINE };
const table = (widths, rows) => new Table({
  columnWidths: widths,
  width: { size: TABLE_W, type: WidthType.DXA },
  borders: { top: bd, bottom: bd, left: bd, right: bd, insideHorizontal: bd, insideVertical: bd },
  rows: rows.map((cells, i) => new TableRow({
    tableHeader: i === 0,
    children: cells.map((c, j) => cell(c, { width: widths[j], header: i === 0 }))
  }))
});

const bullet = (children) => new Paragraph({ children: arr(children), numbering: { reference: 'dash', level: 0 }, spacing: { after: 90, line: 276 } });
const step = (children) => new Paragraph({ children: arr(children), numbering: { reference: 'steps', level: 0 }, spacing: { after: 90, line: 276 } });

const numbering = { config: [
  { reference: 'dash', levels: [{ level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: 420, hanging: 240 } } } }] },
  { reference: 'steps', levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: 420, hanging: 240 } } } }] }
] };

const styles = { default: {
  document: { run: { font: 'Calibri', size: 22, color: '1B1B1B' } },
  heading1: { run: { font: 'Calibri', size: 30, bold: true, color: ACCENT } },
  heading2: { run: { font: 'Calibri', size: 25, bold: true, color: ACCENT } }
} };

const children = [
  new Paragraph({ children: [t('Конструктор футболок', { bold: true, size: 40, color: ACCENT })], spacing: { after: 60 } }),
  new Paragraph({
    children: [t('Как всё настроить самому, без программиста', { size: 26, color: MUTED })],
    spacing: { after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: LINE, space: 6 } }
  }),
  new Paragraph({ children: [t('Инструкция для администратора jetronsport.ru. Обновлено 29.07.2026.', { size: 20, color: MUTED })], spacing: { after: 260 } }),

  p([t('В админке сайта слева есть пункт '), t('«Конструктор футболок»', { bold: true }), t('. Внутри три вкладки: цены печати и надписи, библиотека принтов, изделия и цвета. Не путайте с пунктом «Конструктор формы», это другой конструктор и другие настройки.')]),
  p([t('Изменения появляются у покупателей сразу после обновления страницы конструктора. ', { bold: true }), t('Ничего перезапускать не нужно. Сам конструктор открывается по ссылке '), code('https://jetronsport.ru/tshirt/'), t(' и встроен в страницу «Онлайн-конструктор футболок».')]),
  callout([t('Цена самой футболки сюда не входит. ', { bold: true }), t('Она берётся из карточки товара, как и у конструктора формы. В админке конструктора настраивается только печать и надпись.')]),

  h1('1. Цены печати и надписи'),
  p([t('Вкладка '), t('«Цены печати и надписи»', { bold: true }), t('. Здесь две сетки тарифов, DTF и плёнка, и цена надписи.')]),
  h2('Как устроены ступени'),
  p('Цена печати ступенчатая: конструктор берёт первый тариф, в рамку которого принт помещается целиком. Поэтому ступени идут от меньшей к большей.'),
  table([2600, 2600, 4160], [
    ['Ширина, см', 'Высота, см', 'Что это значит'],
    ['30', '30', 'принт до 30 на 30 считается по этой цене'],
    ['40', '40', 'всё, что больше предыдущей ступени и влезает сюда'],
    ['40', '50', 'самый большой принт']
  ]),
  p(''),
  bullet('В каждой таблице снизу есть две пустые строки: заполните их, чтобы добавить новые ступени.'),
  bullet('Чтобы убрать ступень, очистите её строку и сохраните.'),
  bullet('Строка сохранится, только если заполнены все три поля: ширина, высота и цена.'),
  h2('Надпись'),
  bullet('«Надпись без принта» это цена, когда покупатель заказывает только текст.'),
  bullet('«Скидка на надпись вместе с принтом» в процентах: покупателю она отдельной строкой не показывается, просто уменьшает стоимость надписи.'),
  bullet([t('Кнопка '), t('«Сбросить к значениям по умолчанию»', { bold: true }), t(' возвращает исходные цены.')]),

  h1('2. Библиотека принтов'),
  p([t('Вкладка '), t('«Библиотека принтов»', { bold: true }), t('. Это то, что покупатель видит в окне «Выбрать из библиотеки»: слева список категорий, справа картинки.')]),
  h2('Категории'),
  step([t('Чтобы создать категорию, впишите название в поле '), t('«Новая категория»', { bold: true }), t(' и нажмите «Добавить категорию». Например «23 февраля».')]),
  step([t('Чтобы переименовать, поправьте название в строке категории и нажмите '), t('«Переименовать»', { bold: true }), t('. Картинки останутся на месте.')]),
  step([t('Чтобы поменять порядок, жмите '), t('«выше»', { bold: true }), t(' и '), t('«ниже»', { bold: true }), t('. В этом же порядке категории увидит покупатель.')]),
  step([t('Чтобы удалить категорию целиком, нажмите '), t('«Удалить категорию»', { bold: true }), t('. Файлы картинок при этом остаются на сервере, из конструктора уходит только категория.')]),
  h2('Загрузка картинок'),
  step('Выберите файлы в нужной категории. Можно сразу несколько: удерживайте Ctrl или Shift в окне выбора файлов.'),
  step('Если принты тёмные, поставьте галочку «тёмные принты». Тогда и в админке, и у покупателя в окне библиотеки их превью показывается на тёмной подложке, иначе тёмный рисунок сливается с белым фоном.'),
  step('Нажмите «Загрузить принты».'),
  bullet('Формат PNG, JPG или WebP, до 8 МБ каждый. Лучше всего PNG с прозрачным фоном.'),
  bullet('Если какой-то файл не подошёл, остальные всё равно загрузятся, а в сообщении будет написано, что именно не приняли и почему.'),
  bullet([t('Убрать одну картинку: ссылка '), t('«Убрать»', { bold: true }), t(' под ней.')]),
  bullet([t('Кнопка '), t('«Вернуть исходную библиотеку принтов»', { bold: true }), t(' внизу страницы отменяет все ваши правки библиотеки разом.')]),
  callout([t('Названия файлов можно писать по-русски. ', { bold: true }), t('Сайт сам приведёт их к безопасному виду, и одинаковые имена не затрут друг друга.')])
];

children.push(
  h1('3. Изделия и цвета'),
  p([t('Вкладка '), t('«Изделия и цвета»', { bold: true }), t('. Каждая строка это футболка определённого фасона и цвета, её выбирает покупатель под макетом.')]),
  h2('Как добавить футболку'),
  step('Приготовьте две фотографии: перёд и спина. PNG, JPG или WebP, до 8 МБ. Лучше всего прозрачный фон.'),
  step('Выберите фасон: короткий рукав или оверсайз.'),
  step('Впишите название цвета так, как его увидит покупатель, например «Хаки», и выберите сам цвет для кружка.'),
  step('Загрузите фото спереди, при желании фото сзади. Без второго файла спина покажется тем же кадром.'),
  step('Нажмите «Добавить в конструктор».'),
  h2('Полезно знать'),
  bullet('Если добавить тот же фасон с тем же цветом ещё раз, второй строки не появится: обновятся фотографии. Так удобно заменить неудачный мокап.'),
  bullet([t('Кнопка '), t('«Убрать»', { bold: true }), t(' удаляет футболку. Если это был последний вариант такого цвета, кружок цвета тоже уйдёт, чтобы у покупателя не оставалось пустых вариантов.')]),
  bullet([t('Кнопка '), t('«Вернуть исходный каталог футболок и цветов»', { bold: true }), t(' отменяет ваши правки каталога разом.')]),
  callout([t('Про качество мокапов. ', { bold: true }), t('Покупатель видит именно вашу фотографию, поэтому чем ровнее кадр и чище фон, тем лучше выглядит конструктор. Если подберёте более удачные снимки, просто загрузите их поверх прежних тем же фасоном и цветом.')]),

  h1('4. Зона печати: пунктирная рамка на макете'),
  p('Пунктирная рамка это физическая зона печати: взрослая 40 на 50 см, детская 30 на 40 см. '
    + 'Покупатель не может вынести принт за неё, а размер в сантиметрах считается именно от рамки. '
    + 'Пропорции рамки конструктор держит сам, поэтому 40 на 50 всегда выглядит как 40 на 50.'),
  h2('Как открыть редактор'),
  step('Войдите в админку сайта в этом же браузере.'),
  step([t('Откройте '), t('«Конструктор футболок»', { bold: true }), t(', вкладку '),
        t('«Изделия и цвета»', { bold: true }), t(', и нажмите '),
        t('«Открыть редактор зоны печати»', { bold: true }), t('.')]),
  step([t('Или введите адрес: '), code('https://jetronsport.ru/tshirt/?zones=edit')]),
  step('Внизу слева появится тёмная панель «Редактор зоны печати».'),
  h2('Как править'),
  bullet('Тяните рамку мышью, чтобы переместить её по футболке.'),
  bullet('Тяните круг в правом нижнем углу рамки, чтобы изменить размер. Пропорции 40 на 50 держатся сами, перекосить рамку нельзя.'),
  bullet([t('Нажмите '), t('«Сохранить»', { bold: true }), t('. Появится надпись «Сохранено».')]),
  bullet([t('Кнопка '), t('«Отменить правки»', { bold: true }), t(' перезагружает страницу и возвращает рамку к сохранённой.')]),
  callout([t('Детская зона выводится сама. ', { bold: true }), t('Вы правите взрослую рамку 40 на 50, '
    + 'а детская 30 на 40 считается от её центра. Отдельно её настраивать не нужно.')]),
  p([t('Вернуть исходную рамку: кнопка '), t('«Вернуть исходную зону печати»', { bold: true }),
     t(' на вкладке «Изделия и цвета».')]),
  p('Покупатели увидят новую рамку после обновления страницы конструктора.'),

  h1('5. Цена футболки: из карточки товара'),
  p('Стоимость самого изделия приходит из карточки товара WooCommerce, в конструкторе её нет. Меняете цену в товаре, конструктор подхватывает её сам.'),
  p('В админке конструктора настраивается только то, что добавляется к изделию: печать и надпись.'),

  h1('6. Страница конструктора и меню'),
  p([t('Конструктор встроен в страницу '), t('«Онлайн-конструктор футболок»', { bold: true }), t('. Найдите её в разделе Страницы. Внутри один блок с кодом вставки, его лучше не трогать.')]),
  p([t('Пункт '), t('«Конструктор футболок»', { bold: true }), t(' стоит в подвале сайта рядом с «Конструктором формы», '
    + 'а на телефоне ещё и в меню-бургере. Из верхней шапки пункты убраны: там они ломали её на две строки.')]),
  callout([t('Обратите внимание. ', { bold: true }), t('На сайте два разных меню: основное для компьютера и мобильное. Пункт, добавленный в одно меню, во втором не появится. Если будете переносить конструктор в другой раздел, поправьте оба: Внешний вид, Меню, «Меню основное» и «Меню мобильное».')]),

  h1('Короткая памятка'),
  table([4680, 4680], [
    ['Что нужно', 'Куда идти'],
    ['Изменить цену футболки', 'Товары, нужный товар, поле «Цена»'],
    ['Изменить цену печати', 'Конструктор футболок, вкладка «Цены печати и надписи»'],
    ['Изменить цену надписи', 'Там же, блок «Надпись»'],
    ['Создать категорию принтов', 'Вкладка «Библиотека принтов», поле «Новая категория»'],
    ['Переименовать категорию', 'Там же, поправить название и «Переименовать»'],
    ['Поменять порядок категорий', 'Там же, кнопки «выше» и «ниже»'],
    ['Загрузить принты пачкой', 'Там же, выбрать несколько файлов через Ctrl или Shift'],
    ['Добавить футболку или цвет', 'Вкладка «Изделия и цвета»'],
    ['Заменить фотографию футболки', 'Там же, добавить тот же фасон и цвет заново'],
    ['Поправить рамку печати', 'Кнопка «Открыть редактор зоны печати», тянуть, «Сохранить»']
  ]),
  p(''),
  p([t('Если что-то повело себя не так, как вы ожидали, напишите мне: разберусь и поправлю.', { color: MUTED })])
);

const doc = new Document({
  creator: 'JetronSport',
  title: 'Конструктор футболок: инструкция для администратора',
  description: 'Как настраивать конструктор футболок на jetronsport.ru',
  numbering,
  styles,
  sections: [{
    properties: { page: { margin: { top: 1080, bottom: 1080, left: 1080, right: 1080 } } },
    children
  }]
});

const out = path.join(__dirname, '..', 'Инструкция-конструктор-футболок.docx');
Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync(out, buf);
  console.log('готово:', out, buf.length, 'байт');
});
